const store = { get(k, fallback){ try { const v = localStorage.getItem('prov-'+k); return v ? JSON.parse(v) : fallback; } catch { return fallback; } }, set(k,v){ localStorage.setItem('prov-'+k,JSON.stringify(v)); } };

